local-exec.command:
export VPC=$(aws ec2 describe-vpcs --query "Vpcs[?Tags[?Key=='Name' && Value=='cdktf-eks-vpc-keycloak-golden-cluster']].VpcId"   --output text)
echo "Destroying security-groups"
for SG_ID in $(aws ec2 describe-security-groups --filters Name=vpc-id,Values=$VPC --region eu-west-2 --query 'SecurityGroups[*].[GroupId]' --output text --no-cli-pager); do {
  echo $SG_ID ;
  aws ec2 delete-security-group --group-id $SG_ID || true
} done
